package org.feniello.retrocalc;

import android.graphics.Bitmap;
import android.util.Base64;

/** The same face picture the Apple stack shows when the name is tapped. */
final class FacePortrait {
    static final int SIDE = 80;

    private FacePortrait() {}

    static Bitmap bitmap() {
        byte[] data = Base64.decode(PACKED, Base64.DEFAULT);
        int[] pixels = new int[SIDE * SIDE];
        int limit = Math.min(pixels.length, data.length * 4);
        for (int index = 0; index < limit; index++) {
            int shift = (3 - (index % 4)) * 2;
            int level = (data[index / 4] >> shift) & 3;
            pixels[index] = color(level);
        }
        Bitmap bitmap = Bitmap.createBitmap(SIDE, SIDE, Bitmap.Config.ARGB_8888);
        bitmap.setPixels(pixels, 0, SIDE, 0, 0, SIDE, SIDE);
        return bitmap;
    }

    private static int color(int level) {
        if (level == 2) return 0xFF282828;
        if (level == 1) return 0xFF4A5045;
        return 0xFF60695B;
    }

    private static final String PACKED = "";
}
